-- 182: Original BrillaPrep WASSCE BrillaPrep transitional Woodwork beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_182_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_182_guard;
INSERT INTO _migration_182_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_011' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_3' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of the cap iron on a conventional bench plane?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Set the board width directly","B. Replace the plane sole","C. Help break the shaving and support the cutting edge near the cut","D. Cut circular holes in timber"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Proper cap-iron position influences shaving curl and can reduce tear-out while stiffening the cutting assembly. Therefore the correct answer is C: Help break the shaving and support the cutting edge near the cut.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_011' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_182_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_012' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_3' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which saw is most suitable for cutting accurately across the grain of a board?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A rip saw filed only for cutting along grain","B. A coping saw used as a heavy ripping tool","C. A hacksaw intended for metal stock","D. A crosscut saw"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Crosscut teeth sever fibres across the grain with knife-like edges, producing a more controlled transverse cut. Therefore the correct answer is D: A crosscut saw.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_012' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_182_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_013' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_3' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a chisel bevel normally placed toward the waste in a straight-sided recess?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The flat back can guide the finished face while the bevel enters waste","B. The bevel must crush the finished edge","C. The flat back cannot register against a line","D. The cutting edge works only when reversed repeatedly"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Using the flat back as the reference helps maintain a straight clean wall and directs the wedging action into material being removed. Therefore the correct answer is A: The flat back can guide the finished face while the bevel enters waste.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_013' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_182_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_014' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_3' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does a try square check during preparation of timber?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The moisture content numerically","B. Whether a face or edge is at right angles to its reference","C. The pitch of a screw thread","D. The radius of a circular arc"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Its stock registers on the prepared datum and the blade reveals any gap from a ninety-degree relationship. Therefore the correct answer is B: Whether a face or edge is at right angles to its reference.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_014' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_182_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_015' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_3' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a pilot hole bored before driving a large screw near the end of a board?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase wedging force until the wood cracks","B. Remove the need for correct screw size","C. Reduce splitting and guide the screw accurately","D. Make the screw threads unable to grip"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A correctly sized pilot provides clearance for the core and reduces radial stress while allowing the threads to engage sound surrounding wood. Therefore the correct answer is C: Reduce splitting and guide the screw accurately.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_015' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
